import React, { useState, useEffect } from 'react';
import './App.css';
import api from './api';

// Import components
import Navbar from './components/ui/Navbar';
import Explore from './components/layout/Explore';
import Holdings from './components/layout/Holdings';
import Positions from './components/layout/Positions';
import Orders from './components/layout/Orders';
import WatchlistPage from './components/layout/WatchlistPage';
import Recharge from './components/layout/Recharge';
import StockSearch from './components/trading/StockSearch';
import StockDetails from './components/trading/StockDetails';
import PriceChart from './components/trading/PriceChart';
import TradePanel from './components/trading/TradePanel';
import HoldingsTable from './components/portfolio/HoldingsTable';

function App() {
  // Auth state
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [username, setUsername] = useState('DemoTrader');
  const [password, setPassword] = useState('');
  const [email, setEmail] = useState('');
  const [toastMsg, setToastMsg] = useState('');
  const [loading, setLoading] = useState(false);

  // Trading state
  const [symbol, setSymbol] = useState('RELIANCE');
  const [price, setPrice] = useState(null);
  const [balance, setBalance] = useState(100000);
  const [portfolio, setPortfolio] = useState([]);
  const [activeTab, setActiveTab] = useState('explore');

  useEffect(() => {
    checkSession();
  }, []);

  useEffect(() => {
    if (isLoggedIn) {
      fetchPortfolio();
      fetchPrice();
      const interval = setInterval(() => {
        fetchPortfolio();
        if (activeTab === 'trading') {
          fetchPrice();
        }
      }, 15000);
      return () => clearInterval(interval);
    }
  }, [isLoggedIn, activeTab, symbol]);

  const showToast = (msg) => {
    setToastMsg(msg);
    setTimeout(() => setToastMsg(''), 4000);
  };

  const checkSession = async () => {
    try {
      const data = await api.getMe();
      if (data.logged_in) {
        setIsLoggedIn(true);
        setUsername(data.username);
        setBalance(data.balance || 100000);
      } else {
        // Auto guest login for frictionless experience
        loginAsGuest();
      }
    } catch (e) {
      loginAsGuest();
    }
  };

  const loginAsGuest = async () => {
    try {
      const data = await api.loginGuest();
      setIsLoggedIn(true);
      setUsername(data.user || 'DemoTrader');
      setBalance(data.balance || 100000);
    } catch (e) {
      console.error("Guest login failed:", e);
    }
  };

  const handleLogin = async () => {
    setLoading(true);
    try {
      const data = await api.login(username, password);
      setIsLoggedIn(true);
      setUsername(data.user);
      setBalance(data.balance || 100000);
      showToast(`Welcome back, ${data.user}!`);
    } catch (error) {
      showToast(error.message || 'Login failed');
    }
    setLoading(false);
  };

  const handleRegister = async () => {
    setLoading(true);
    try {
      const data = await api.register(username, email, password);
      setIsLoggedIn(true);
      setUsername(data.user);
      setBalance(data.balance || 100000);
      showToast(data.message || 'Account created!');
    } catch (error) {
      showToast(error.message || 'Registration failed');
    }
    setLoading(false);
  };

  const handleLogout = async () => {
    try {
      await api.logout();
    } catch (e) {}
    setIsLoggedIn(false);
    showToast('Logged out');
  };

  // Trading functions
  const fetchPrice = async () => {
    if (!symbol) return;
    try {
      const data = await api.getPrice(symbol);
      if (data.price) {
        setPrice(data.price);
      }
    } catch (error) {
      console.error('Error fetching price:', error);
    }
  };

  const fetchPortfolio = async () => {
    try {
      const data = await api.getPortfolio();
      if (data.portfolio !== undefined) {
        setPortfolio(data.portfolio || []);
        setBalance(data.balance || 0);
      }
    } catch (error) {
      console.error('Error fetching portfolio:', error);
    }
  };

  const handleBuy = async (quantity) => {
    setLoading(true);
    try {
      const data = await api.buyStock(symbol, quantity);
      showToast(data.message || 'Order executed!');
      if (data.balance !== undefined) {
        setBalance(data.balance);
        fetchPortfolio();
      }
    } catch (error) {
      showToast(error.message || 'Error buying stock');
    }
    setLoading(false);
  };

  const handleSell = async (quantity) => {
    setLoading(true);
    try {
      const data = await api.sellStock(symbol, quantity);
      showToast(data.message || 'Order executed!');
      if (data.balance !== undefined) {
        setBalance(data.balance);
        fetchPortfolio();
      }
    } catch (error) {
      showToast(error.message || 'Error selling stock');
    }
    setLoading(false);
  };

  const handleSelectStock = (selectedSymbol) => {
    setSymbol(selectedSymbol);
    setActiveTab('trading');
    setTimeout(() => fetchPrice(), 100);
  };

  // Render Login Modal if not logged in
  if (!isLoggedIn) {
    return (
      <div style={{
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        minHeight: '100vh',
        background: 'var(--bg-dark)',
        padding: '20px'
      }}>
        <div className="soft-card fade-in" style={{
          padding: '40px',
          width: '100%',
          maxWidth: '420px',
          textAlign: 'center'
        }}>
          <div style={{
            width: '56px',
            height: '56px',
            borderRadius: '16px',
            background: 'linear-gradient(135deg, #38bdf8 0%, #10b981 100%)',
            display: 'inline-flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: '28px',
            color: '#ffffff',
            marginBottom: '16px',
            boxShadow: 'var(--shadow-glow)'
          }}>
            📈
          </div>
          <h1 style={{ color: 'var(--text-primary)', fontSize: '24px', fontWeight: '800' }}>DemoTrader</h1>
          <p style={{ color: 'var(--accent-emerald)', fontWeight: '700', fontSize: '14px', marginTop: '4px' }}>
            🎉 Free ₹1,00,000 Demo Funds Included!
          </p>

          <button
            onClick={loginAsGuest}
            className="soft-btn soft-btn-success"
            style={{ width: '100%', padding: '14px', marginTop: '24px', fontSize: '15px', fontWeight: '800' }}
          >
            🚀 Continue as Demo Trader
          </button>

          <div style={{ margin: '20px 0', borderBottom: '1px solid var(--border-color)', position: 'relative' }}>
            <span style={{
              position: 'absolute',
              top: '-10px',
              left: '50%',
              transform: 'translateX(-50%)',
              background: 'var(--bg-surface)',
              padding: '0 10px',
              color: 'var(--text-muted)',
              fontSize: '12px'
            }}>OR</span>
          </div>

          <input
            type="text"
            placeholder="Username"
            className="soft-input"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            style={{ width: '100%', marginBottom: '10px' }}
          />
          <input
            type="password"
            placeholder="Password"
            className="soft-input"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            style={{ width: '100%', marginBottom: '14px' }}
          />

          <button
            onClick={handleLogin}
            disabled={loading}
            className="soft-btn soft-btn-primary"
            style={{ width: '100%', padding: '12px', fontSize: '14px' }}
          >
            {loading ? 'Logging in...' : 'Sign In'}
          </button>
        </div>
      </div>
    );
  }

  // Render main app tabs
  const renderContent = () => {
    switch(activeTab) {
      case 'explore':
        return <Explore onSelectStock={handleSelectStock} />;

      case 'holdings':
        return <Holdings portfolio={portfolio} balance={balance} />;

      case 'positions':
        return <Positions />;

      case 'orders':
        return <Orders />;

      case 'watchlist':
        return <WatchlistPage onSelectStock={handleSelectStock} />;

      case 'recharge':
        return (
          <Recharge 
            balance={balance}
            onRecharge={(newBalance) => {
              setBalance(newBalance);
              fetchPortfolio();
            }}
          />
        );

      case 'trading':
        return (
          <div className="fade-in" style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
            <StockSearch onSelectStock={handleSelectStock} />
            <StockDetails symbol={symbol} />

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(340px, 1fr))', gap: '20px' }}>
              <div style={{ flex: 2 }}>
                <PriceChart symbol={symbol} />
              </div>
              <div style={{ flex: 1 }}>
                <TradePanel
                  symbol={symbol}
                  price={price}
                  balance={balance}
                  onBuy={handleBuy}
                  onSell={handleSell}
                  loading={loading}
                />
              </div>
            </div>
            <HoldingsTable holdings={portfolio} />
          </div>
        );

      default:
        return <Explore onSelectStock={handleSelectStock} />;
    }
  };

  return (
    <div className="app-container">
      <Navbar
        username={username}
        balance={balance}
        onLogout={handleLogout}
        setActiveTab={setActiveTab}
        activeTab={activeTab}
      />

      <main className="main-content">
        {renderContent()}
      </main>

      {/* Floating Toast Notification */}
      {toastMsg && (
        <div className="toast-banner fade-in">
          <span>🔔</span>
          <span style={{ fontWeight: '600', fontSize: '14px' }}>{toastMsg}</span>
        </div>
      )}
    </div>
  );
}

export default App;
